pub trait Dispatch: Sized + 'static {
    fn invoke(
        store: StoreContextMut<'_, Self>,
        operation: &'static Operation,
        function_type: ComponentFunc,
        parameters: &[Val],
        results: &mut [Val],
    ) -> wasmtime::Result<()>;

    fn drop_resource(
        store: StoreContextMut<'_, Self>,
        resource: &'static ResourceDescriptor,
        representation: u32,
    ) -> wasmtime::Result<()>;
}

